<script setup>
import{ref,reactive,computed,watch,onMounted,onUnmounted,defineComponent,h,nextTick}from'vue'
import{defineStore}from'pinia'
import{createRouter,createMemoryHistory,RouterView}from'vue-router'
import{labs}from'./config'
const id=new URLSearchParams(location.search).get('lab'),config=labs.find(x=>x.id===id),kind=config?.kind||'index'
const storageKey='vue-lab-v1:'+id;let saved={};try{saved=JSON.parse(localStorage.getItem(storageKey)||'{}')}catch{}
const passed=ref(saved.passed||[false,false,false]),hint=ref(false),feedback=ref(''),state=reactive({name:'Суп',stock:2,quantity:1,query:'',category:'',submitted:'',submits:0,heading:'Карточка от родителя',shown:true,counter:0,watchCalls:0,oldValue:'',newValue:'',mounted:false,ticks:0,cleaned:false,selected:1,slotTitle:'Мой заказ',slotClicks:0,protect:false,result:'',busy:false,session:false,cookie:false,me:'Гость',boot:'unknown',meRequests:0,fail:false,version:1,confirmed:1,draft:2,status:'',orders:0,key:'order-001',address:'Main street 10',lost:true,debug:'input',boundary:''})
const products=ref([{id:1,name:'Суп',category_id:1,active:true,price:35000},{id:2,name:'Чай',category_id:2,active:true,price:9000},{id:3,name:'Салат',category_id:1,active:true,price:28000}])
const filtered=computed(()=>products.value.filter(p=>(!state.category||p.category_id===Number(state.category))&&p.name.toLowerCase().includes(state.query.trim().toLowerCase())))
const code=ref(saved.code||({dom:'return name;',binding:'return false;',computed:'return product.active;',emits:'return total;'}[kind]||''))
function persist(){try{localStorage.setItem(storageKey,JSON.stringify({passed:passed.value,code:code.value}))}catch{}}
function mark(i){passed.value[i]=true;persist()}
function reset(){try{localStorage.removeItem(storageKey)}catch{}location.reload()}
watch(code,persist)
const step=computed(()=>Math.min(3,passed.value.findIndex(x=>!x)+1||3))
const codeResult=ref('')
let editorGeneration=0
function evaluate(mode){return new Promise(resolve=>{
 const payload={kind,code:code.value,mode,input:{args:kind==='dom'?[state.name]:kind==='binding'?[state.stock]:[chosen.value.length,1],products:JSON.parse(JSON.stringify(products.value)),query:state.query}}
 const worker=new Worker(new URL('./evaluate.worker.js',import.meta.url),{type:'module'})
 const finish=data=>{clearTimeout(timeout);worker.terminate();resolve(data)}
 let timeout=setTimeout(()=>finish({ok:false,error:'Исполнитель не загрузился. Проверьте соединение и повторите.'}),10000)
 worker.onmessage=({data})=>{if(data.ready){clearTimeout(timeout);timeout=setTimeout(()=>finish({ok:false,error:'Выполнение заняло слишком много времени. Проверьте завершение функции.'}),500);worker.postMessage(payload)}else finish(data)}
 worker.onerror=()=>finish({ok:false,error:'Код не удалось выполнить.'})
})}

async function checkCode(){const result=await evaluate('check');feedback.value=!result.ok?result.error:result.passed?'Проверки поведения пройдены.':'Пока не все случаи проходят. Сверьте условие и попробуйте другие данные.';if(result.passed)mark(2)}
const inputA=ref(null),inputB=ref(null)
function conditionsInput(){if(inputA.value?.value&&inputB.value?.value)mark(0)}
function toggleBlocks(){state.shown=!state.shown;if(!state.shown)mark(1);else if(passed.value[1])mark(2)}
watch(()=>state.name,()=>{if(state.name!=='Суп'){if(kind==='dom'||kind==='reactivity')mark(kind==='dom'?0:1)}})
watch(()=>state.stock,value=>{if(kind==='binding')mark(value===0?0:1)})
watch(()=>state.query,(value,old)=>{if(kind==='watch'){state.watchCalls++;state.oldValue=old;state.newValue=value;if(!passed.value[0])mark(0);else if(passed.value[1])mark(2)}if(kind==='computed'&&value.toLowerCase().includes('чай'))mark(0)})
watch(()=>state.category,()=>{if(kind==='computed')mark(1)})
watch(()=>state.slotTitle,value=>{if(kind==='slots')mark(value?0:1)})
function submit(){state.submitted=state.name;state.submits++;mark(state.submits===1?1:2)}
const ChildCard=defineComponent({props:{name:String,price:Number,id:Number,selectable:Boolean},emits:['choose'],setup(p,{emit}){return()=>h('article',{class:'child'},[h('strong',p.name),h('p',p.price?`${p.price/100} ₽`:'Переданные props'),p.selectable?h('button',{onClick:()=>emit('choose',p.id)},'Выбрать '+p.name):null])}})
const chosen=ref([])
watch([code,()=>state.name,()=>state.stock,()=>state.query,()=>chosen.value.length],async()=>{if(!code.value)return;const mine=++editorGeneration;const result=await evaluate('preview');if(mine===editorGeneration)codeResult.value=result.ok?result.result:result.error},{immediate:true})
function choose(id){chosen.value.push(id);mark(id===1?0:1)}
const SlotCard=defineComponent({setup(p,{slots}){return()=>h('article',{class:'child'},[h('header',slots.header?.()||'Заголовок по умолчанию'),h('section',slots.default?.()),h('footer',slots.actions?.())])}})
const TimerChild=defineComponent({emits:['tick','cleaned'],setup(p,{emit}){let timer;onMounted(()=>{timer=setInterval(()=>emit('tick'),200)});onUnmounted(()=>{clearInterval(timer);emit('cleaned')});return()=>h('p',{class:'child'},'Компонент смонтирован. Таймер работает.')}})
let cleanupCheck
function toggleTimer(){if(!state.mounted){state.mounted=true;state.cleaned=false;mark(0)}else{state.mounted=false;const before=state.ticks;cleanupCheck=setTimeout(()=>{if(state.ticks===before&&state.cleaned)mark(2)},500)}}
function onTick(){state.ticks++;if(state.ticks>=2)mark(1)}
onUnmounted(()=>clearTimeout(cleanupCheck))
const byId=ref(false),keyRows=ref([{id:1,name:'Суп'},{id:2,name:'Чай'},{id:3,name:'Салат'}])
const KeyRow=defineComponent({props:{item:Object},emits:['edited'],setup(p,{emit}){const draft=ref(p.item.name);return()=>h('label',[h('strong','Товар'+p.item.id+': '+p.item.name),h('input',{value:draft.value,'aria-label':'Название строки '+p.item.id,onInput:e=>{draft.value=e.target.value;emit('edited')}})])}})
function changeKeyMode(){keyRows.value=[{id:1,name:'Суп'},{id:2,name:'Чай'},{id:3,name:'Салат'}]}
function removeFirst(){keyRows.value.shift();mark(byId.value?2:1)}
const currentRoute=ref('/catalog'),routeText=ref('Каталог'),router=createRouter({history:createMemoryHistory(),routes:[{path:'/catalog',component:{render:()=>h('p','Каталог')}},{path:'/products/:id',component:{render:()=>h('p','Товар')}},{path:'/:pathMatch(.*)*',component:{render:()=>h('p','Страница404')}}]})
router.afterEach(to=>{currentRoute.value=to.fullPath;routeText.value=to.params.id?(products.value.find(p=>p.id===Number(to.params.id))?.name||'Товар не найден'):to.path==='/catalog'?'Каталог':'Страница404';if(kind==='router'){if(to.path==='/products/1')mark(0);if(to.path==='/catalog'&&passed.value[0])mark(1);if(to.name===undefined&&to.path==='/missing')mark(2)}if(kind==='params'){if(to.params.id==='2')mark(0);if(to.query.search)mark(1);if(to.params.id==='99')mark(2)}})
router.push('/catalog')
const useLabStore=defineStore('lab-cart',()=>{const soup=ref(0),tea=ref(0),total=computed(()=>soup.value+tea.value);return{soup,tea,total}});const shared=useLabStore()
const SharedHeader=defineComponent({setup(){const store=useLabStore();return()=>h('header',{class:'parent'},'Шапка: всего '+store.total)}})
const SharedItem=defineComponent({props:{which:String,label:String},emits:['added'],setup(p,{emit}){const store=useLabStore();return()=>h('article',{class:'child'},[h('p',p.label+': '+store[p.which]),h('button',{onClick:()=>{store[p.which]++;emit('added',p.which)}},'Добавить '+p.label.toLowerCase())])}})
function addShared(which){if(which==='soup')mark(0);if(which==='tea')mark(1);if(shared.total>=3)mark(2)}
function useCounter(){const count=ref(0);return{count}}
const IndependentCounter=defineComponent({props:{label:String},emits:['changed','reset'],setup(p,{emit}){const{count}=useCounter();return()=>h('article',{class:'child'},[h('strong',p.label+': '+count.value),h('button',{onClick:()=>{count.value++;emit('changed')}},'+1 '+p.label),h('button',{onClick:()=>{count.value=0;emit('reset')}},'Сбросить '+p.label)])}})
let timerIds=[]
function sleep(ms){return new Promise(resolve=>{const timer=setTimeout(resolve,ms);timerIds.push(timer)})}
onUnmounted(()=>timerIds.forEach(clearTimeout))
async function runRace(){if(state.busy)return;state.busy=true;state.result='';const generation=2;await Promise.all([sleep(700).then(()=>{if(!state.protect||generation===1)state.result='Суп'}),sleep(160).then(()=>{state.result='Чай'})]);state.busy=false;if(state.protect){mark(1);if(state.result==='Чай')mark(2)}else mark(0)}
function loginModel(){state.session=true;state.cookie=true;state.me='Профиль ещё не запрошен';mark(0)}
function profileModel(){state.me=state.cookie&&state.session?'Покупатель7 · HTTP200':'Нет действующей сессии · HTTP401';if(state.session)mark(1);else if(passed.value[1])mark(2)}
let inflight=null
function bootstrap(){if(inflight){mark(1);return inflight}state.boot='unknown';state.meRequests++;mark(0);inflight=sleep(600).then(()=>{state.boot='authenticated';inflight=null});return inflight}
async function saveAck(){if(state.busy)return;state.busy=true;state.status='Запись ожидает ответа';mark(0);await sleep(500);state.busy=false;if(state.fail){state.status='Ошибка: подтверждённая корзина сохранена';mark(2)}else{state.confirmed=state.draft;state.version++;state.status='Подтверждено сервером';mark(1)}}
const server=reactive({version:1,quantity:1}),a=reactive({version:1,quantity:2,result:''}),b=reactive({version:1,quantity:3,result:''})
function saveVersion(tab){const x=tab==='A'?a:b;if(x.version!==server.version){x.result='409: устаревшая версия';if(tab==='B')mark(1);return}server.quantity=x.quantity;server.version++;x.version=server.version;x.result='200: сохранено';if(tab==='A')mark(0);if(tab==='B'&&passed.value[1])mark(2)}
const commands=new Map()
function checkoutModel(changed=false){const key=state.key;const body=JSON.stringify({cart_version:2,address:changed?'Other street 20':state.address});const existing=commands.get(key);if(existing){if(existing.body!==body){state.status='409: ключ уже связан с другой командой';mark(2)}else{state.status='200: прежний заказ №'+existing.id;mark(1)}return}const id=++state.orders;commands.set(key,{id,body});state.status=state.lost?'Заказ сохранён,ответ потерялся':'201: заказ №'+id;mark(0)}
const debugInfo=computed(()=>({input:{symptom:'Форма не отправляется',detail:'Email без @; HTTP-запроса ещё нет',correct:'frontend',label:'клиентская форма'},cors:{symptom:'Браузер не даёт прочитать ответ',detail:'Origin: http://localhost:5174,разрешён только5173',correct:'browser',label:'браузер и Origin'},version:{symptom:'Сохранение корзины отклонено',detail:'HTTP409 cart_version_conflict · request_id: req-42',correct:'api',label:'серверный договор'}})[state.debug])
function diagnose(){const ok=state.boundary===debugInfo.value.correct;feedback.value=ok?'Верно. Вы нашли границу,на которой возник отказ.':'Сопоставьте симптомы с тем,успел ли запрос дойти до сервера.';if(ok)mark({input:0,cors:1,version:2}[state.debug])}
</script>
<template>
<section v-if="kind==='index'" class="lab-index"><h1>Практика Vue</h1><a v-for="lab in labs" :key="lab.id" :href="'?lab='+lab.id">{{lab.id}} · {{lab.goals[0]}}</a></section>
<div v-else class="lab">
 <section class="goal"><div class="goal-top"><strong>{{passed.every(Boolean)?'Все задания выполнены':config.goals[step-1]}}</strong><small>Выполнено {{passed.filter(Boolean).length}} из3</small></div><button class="hint-button" @click="hint=!hint">Небольшая подсказка</button><p v-if="hint">{{config.hints[step-1]}}</p></section>
 <section class="work">
 <template v-if="kind==='dom'"><label>Название блюда<input v-model="state.name"></label><div class="columns"><article class="state"><strong>Состояние</strong><code>name: {{state.name}}</code></article><article class="preview"><strong>Экран</strong><p>{{state.submitted||'Суп'}}</p></article></div><button @click="state.submitted=state.name;mark(1)">Обновить экран из состояния</button></template>
 <template v-if="kind==='keys'"><label class="check"><input v-model="byId" type="checkbox" @change="changeKeyMode">Использовать key=id</label><div :key="String(byId)" class="state"><KeyRow v-for="(item,index) in keyRows" :key="byId?item.id:index" :item="item" @edited="mark(0)"/></div><button :disabled="keyRows.length<2" @click="removeFirst">Удалить первую строку</button><p>Слева в каждой строке текущий товар,в поле — локальное состояние экземпляра.</p></template>
 <template v-if="kind==='binding'"><label>Остаток<input v-model.number="state.stock" type="number" min="0"></label><article class="preview" :class="{sold:state.stock===0}"><h2>{{state.name}}</h2><button :disabled="state.stock===0">{{state.stock===0?'Закончился':'Выбрать'}}</button><code>:disabled = {{state.stock===0}}</code></article></template>
 <template v-if="kind==='reactivity'"><label>Название<input v-model="state.name"></label><article class="preview"><h2>{{state.name}}</h2><p>Количество: {{state.quantity}}</p><button @click="state.quantity++;mark(0)">Увеличить количество</button><button @click="state.name='Чай';state.quantity=1;mark(2)">Заменить поля состояния</button></article><code>ref(quantity): {{state.quantity}} · reactive.name: {{state.name}}</code></template>
 <template v-if="kind==='conditions'"><div class="columns"><article><strong>v-if</strong><div v-if="state.shown"><input ref="inputA" placeholder="Введите текстA" @input="conditionsInput"></div></article><article><strong>v-show</strong><div v-show="state.shown"><input ref="inputB" placeholder="Введите текстB" @input="conditionsInput"></div></article></div><button @click="toggleBlocks">{{state.shown?'Скрыть блоки':'Показать блоки'}}</button><p class="result">v-if: {{inputA?'элемент существует':'элемента нет'}} · v-show: элемент существует</p></template>
 <template v-if="kind==='events'"><form @submit.prevent="submit"><label>Название<input v-model="state.name" @input="mark(0)"></label><button>Отправить форму</button></form><div class="state"><p>Текущее значение: {{state.name}}</p><p>Последняя отправка: {{state.submitted||'—'}}</p><p>Событий submit: {{state.submits}}</p></div></template>
 <template v-if="kind==='computed'"><div class="columns"><label>Поиск<input v-model="state.query"></label><label>Категория<select v-model="state.category"><option value="">Все</option><option value="1">Еда</option><option value="2">Напитки</option></select></label></div><div class="product-list"><article v-for="p in filtered" :key="p.id">{{p.name}} · {{p.price/100}}₽</article><p v-if="!filtered.length">Ничего не найдено</p></div><p>Исходных товаров: {{products.length}} · показано: {{filtered.length}}</p></template>
 <template v-if="kind==='props'"><div class="parent"><strong>Родитель</strong><label>Название<input v-model="state.name" @input="mark(0)"></label><label>Цена в копейках<input v-model.number="products[0].price" type="number" @input="mark(1)"></label></div><div class="columns"><ChildCard :name="state.name" :price="products[0].price" :id="1"/><ChildCard :name="products[state.selected-1].name" :price="products[state.selected-1].price" :id="2"/></div><button @click="state.selected=state.selected===1?2:1;mark(2)">Сменить товар второй карточки</button></template>
 <template v-if="kind==='emits'"><div class="parent"><strong>Родитель: выбрано {{chosen.length}}</strong><p>События: {{chosen.join(', ')||'ещё нет'}}</p></div><div class="columns"><ChildCard :id="1" name="Суп" selectable @choose="choose"/><ChildCard :id="2" name="Чай" selectable @choose="choose"/></div></template>
 <template v-if="kind==='slots'"><label>Заголовок слота<input v-model="state.slotTitle"></label><SlotCard><template v-if="state.slotTitle" #header><h2>{{state.slotTitle}}</h2></template><p>Состав заказа задаёт родитель.</p><template #actions><button @click="state.slotClicks++;mark(2)">Действие родителя</button></template></SlotCard><p>Нажатий: {{state.slotClicks}}</p></template>
 <template v-if="kind==='watch'"><label>Строка поиска<input v-model="state.query"></label><button @click="state.counter++;mark(1)">Изменить посторонний счётчик</button><div class="state"><p>Посторонний счётчик: {{state.counter}}</p><p>Вызовов watch: {{state.watchCalls}}</p><p>Старое: {{state.oldValue||'пусто'}} → новое: {{state.newValue||'пусто'}}</p></div></template>
 <template v-if="kind==='lifecycle'"><button @click="toggleTimer">{{state.mounted?'Удалить компонент':'Создать компонент'}}</button><TimerChild v-if="state.mounted" @tick="onTick" @cleaned="state.cleaned=true"/><div class="state"><p>Тиков таймера: {{state.ticks}}</p><p>Очистка выполнена: {{state.cleaned?'да':'нет'}}</p></div></template>
 <template v-if="kind==='router'"><code>URL стенда: {{currentRoute}}</code><nav><button @click="router.push('/catalog')">Каталог</button><button @click="router.push('/products/1')">Товар</button><button @click="router.back()">Назад</button><button @click="router.push('/missing')">Неизвестный путь</button></nav><article class="preview"><h2>{{routeText}}</h2><RouterView :route="router.currentRoute.value"/></article></template>
 <template v-if="kind==='params'"><code>URL стенда: {{currentRoute}}</code><nav><button @click="router.push('/products/2')">Товар2</button><button @click="router.push({path:'/catalog',query:{search:'чай'}})">Поиск «чай»</button><button @click="router.push('/products/99')">Товар99</button></nav><article class="preview"><h2>{{routeText}}</h2><RouterView :route="router.currentRoute.value"/><p>Параметры берутся из маршрута.</p></article></template>
 <template v-if="kind==='pinia'"><SharedHeader/><div class="columns"><SharedItem which="soup" label="Суп" @added="addShared"/><SharedItem which="tea" label="Чай" @added="addShared"/></div><div class="state">Корзина: {{shared.soup}} + {{shared.tea}} = {{shared.total}}</div></template>
 <template v-if="kind==='composable'"><div class="columns"><IndependentCounter label="A" @changed="mark(0)" @reset="mark(2)"/><IndependentCounter label="B" @changed="mark(1)"/></div><p>Каждый компонент вызвал один и тот же composable со своим ref.</p></template>
 <template v-if="kind==='race'"><p class="model-note">Управляемая модель двух ответов: старый «суп»700мс,новый «чай»160мс.</p><label class="check"><input v-model="state.protect" type="checkbox" :disabled="state.busy">Исключать устаревшие ответы</label><button :disabled="state.busy" @click="runRace">Отправить два поиска</button><article class="preview"><strong>Последний поиск: чай</strong><p>{{state.busy?'Ждём оба ответа…':state.result||'Ещё не отправлены'}}</p></article></template>
 <template v-if="kind==='session'"><p class="model-note">Модель сессии,без настоящего аккаунта.</p><nav><button @click="loginModel">Войти</button><button @click="profileModel">Запросить профиль</button><button @click="state.session=false;state.cookie=false;profileModel()">Выйти</button></nav><div class="columns"><article class="state">Серверная сессия: {{state.session?'есть':'нет'}}</article><article class="state">HttpOnly-cookie: {{state.cookie?'есть,JS её не читает':'нет'}}</article></div><p class="result">{{state.me}}</p></template>
 <template v-if="kind==='bootstrap'"><p class="model-note">Модель проверки me с задержкой600мс.</p><button @click="bootstrap">Восстановить сессию</button><button :disabled="state.boot!=='authenticated'" @click="state.boot='guest';mark(2)">Получить401</button><article class="preview"><h2>{{state.boot==='unknown'?'Проверяем сессию…':state.boot==='guest'?'Гостевой экран':'Личный кабинет'}}</h2><p>Запросов me: {{state.meRequests}}</p></article></template>
 <template v-if="kind==='ack'"><p class="model-note">Модель сохранения: ответы подтверждают состояние.</p><label>Желаемое количество<input v-model.number="state.draft" type="number" min="1" max="100"></label><label class="check"><input v-model="state.fail" type="checkbox">Следующий запрос завершится ошибкой</label><button :disabled="state.busy" @click="saveAck">Сохранить</button><article class="state">Подтверждено: {{state.confirmed}} · версия {{state.version}}</article><p class="result">{{state.status}}</p></template>
 <template v-if="kind==='versions'"><p class="model-note">Модель одной серверной корзины и двух вкладок.</p><article class="parent">Сервер: количество {{server.quantity}} · версия {{server.version}}</article><div class="columns"><article class="child"><h2>ВкладкаA</h2><p>Ожидает v{{a.version}}</p><input v-model.number="a.quantity" type="number" min="1"><button @click="saveVersion('A')">СохранитьA</button><p>{{a.result}}</p></article><article class="child"><h2>ВкладкаB</h2><p>Ожидает v{{b.version}}</p><input v-model.number="b.quantity" type="number" min="1"><button @click="saveVersion('B')">СохранитьB</button><button @click="b.version=server.version;b.quantity=server.quantity;b.result='Перечитано'">ПеречитатьB</button><p>{{b.result}}</p></article></div></template>
 <template v-if="kind==='idempotency'"><p class="model-note">Модель обработки команды,не настоящий заказ.</p><code>key: {{state.key}} · cart_version:2</code><p>Исходный адрес: {{state.address}}</p><nav><button @click="checkoutModel()">{{state.orders?'Повторить прежнюю команду':'Создать и потерять ответ'}}</button><button :disabled="!state.orders" @click="checkoutModel(true)">Другой адрес с тем же ключом</button></nav><article class="state"><strong>Заказов на сервере: {{state.orders}}</strong><p>{{state.status}}</p></article></template>
 <template v-if="kind==='debug'"><label>Ситуация<select v-model="state.debug"><option value="input">Ошибка ввода</option><option value="cors">Отказ Origin</option><option value="version">Конфликт версии</option></select></label><article class="preview"><h2>{{debugInfo.symptom}}</h2><code>{{debugInfo.detail}}</code></article><label>Где искать причину?<select v-model="state.boundary"><option value="">Выберите границу</option><option value="frontend">Логика формы</option><option value="browser">Браузер и Origin</option><option value="api">Договор API и состояние сервера</option></select></label><button @click="diagnose">Проверить гипотезу</button></template>
 <section v-if="['dom','binding','computed','emits'].includes(kind)" class="editor"><label>Допишите тело функции <code>{{kind==='dom'?'label(name)':kind==='binding'?'disabled(stock)':kind==='computed'?'matches(product,query)':'add(total,quantity)'}}</code><textarea v-model="code" spellcheck="false" rows="3"/></label><p>{{kind==='dom'?'Функция возвращает строку «Блюдо: название».':kind==='binding'?'Верните true только при нулевом остатке.':kind==='computed'?'Верните true для активного товара,имя которого содержит запрос без учёта регистра и крайних пробелов.':'Верните новое общее количество после добавления quantity.'}}</p><p class="code-result">Результат вашей функции: <strong>{{codeResult}}</strong></p><button @click="checkCode">Проверить код</button></section>
 <p v-if="feedback" class="result" role="status">{{feedback}}</p>
 </section><footer><button class="reset" @click="reset">Начать заново</button></footer>
</div>
</template>
